(function(){const scenarios=[],assert=(v,m)=>{if(!v)throw Error(m);},run=(name,fn)=>{fn();scenarios.push(name);};let model,api,original;
 run('native style command patches sixteen types with one exact undo',()=>{nativeInit(0,{series:[]});model=nativeModel;api=nativeAPI;for(const type of Aster.DRAWING_TYPES)api.addDrawing({id:type,type,points:['longposition','shortposition'].includes(type)?[{time:10.25,price:20},{time:10.25,price:type==='longposition'?19:21},{time:10.25,price:type==='longposition'?22:18},{time:11.25,price:20}]:Array.from({length:type==='freehand'?4:Aster.drawingPointCount(type)},(_,i)=>({time:i+.25,price:5+i})),...(type==='text'?{text:'held'}:{})});original=model.drawings.items.slice();const h=model.drawings.undoStack.length,r=nativeCommand('setDrawingsStyle',[Aster.DRAWING_TYPES,{color:'#abc',fill:'#def',width:3,font:'italic 24px monospace'}]);assert(r.changed===16&&!r.invalidationFailed&&model.drawings.undoStack.length===h+1,'receipt and history');assert(model.drawings.items.every((d,i)=>d.points===original[i].points&&d.style.color==='#aabbccff'&&d.style.font==='italic 24px monospace'),'merge and anchors');api.undo();assert(model.drawings.items.every((d,i)=>d===original[i]),'undo identity');api.redo();});
 run('normalized noop and orphan CSS preserve unrelated state',()=>{const d=model.drawings,items=d.items,u=d.undoStack,r=d.redoStack;assert(api.setDrawingsStyle(['text'],{color:'#aabbccff'}).changed===0&&d.items===items&&d.undoStack===u&&d.redoStack===r,'noop');d.add({id:'orphan',type:'horizontal',panel:'missing',points:[{time:1.25,price:2}],style:{color:'hsl(0 100% 50%)'}});assert(api.setDrawingsStyle(['orphan'],{width:4}).changed===1&&d.items[d.items.length-1].style.color==='hsl(0 100% 50%)','omitted CSS');const before=d.items;let failed=false;try{api.setDrawingsStyle(['text','orphan'],{fill:null});}catch{failed=true;}assert(failed&&d.items===before,'invalid atomic');});
 run('style observer reentry preserves state and releases listeners',()=>{api.invalidate=()=>{api.invalidate=()=>{};api.deleteDrawings(['horizontal']);throw Error('observer');};const receipt=api.setDrawingsStyle(['text'],{width:5});assert(receipt.changed===1&&receipt.invalidationFailed&&!model.drawings.items.some(d=>d.id==='horizontal'),'observer');const store=model.store;model.dispose();assert(store.listeners.size===0,'cleanup');});
 return JSON.stringify({case:'drawing-style-quickjs',passed:true,checks:3,scenarios});})()
